UPDATE robot_point SET updated_at = now(), synced_at = now()
, x = #{x}
, y = #{y}
, z = #{z}
, device_resource_id = #{deviceResourceId}
, action = #{action}
 WHERE tenant_id = #{tenantId} AND island_id = #{islandId} AND code = #{code}

UPDATE error_code
scope = #{scope}, severity = #{severity}::error_severity, title = #{title}, detail = #{detail},
WHERE tenant_id = #{param1} AND id = #{param2}

UPDATE experiment
   SET priority = (CASE id

    WHEN #{one} THEN 100 - #{idx}

    ELSE priority END),
       updated_at = now()
 WHERE tenant_id = #{param1}
   AND id IN

